descShort: {
  en: "The inner journey is a silent return from the external expression of life toward the inner being, where the fusion of the conscious",
  
  bn: "অন্তর্যাত্রা জীবনের বাহ্যিক প্রকাশ থেকে অন্তর্গত সত্তার দিকে এক নীরব প্রত্যাবর্তন, যেখানে সূর্য ও চন্দ্রের প্রতিবিম্বে সচেতন ও",
  
  hi: "अंतर्मुखी यात्रा जीवन की बाहरी अभिव्यक्ति से आंतरिक सत्ता की ओर एक मौन प्रत्यावर्तन है, जहाँ सूर्य और चंद्रमा के प्रतिबिंबों में चेतन और अचेतन मन का समन्वय",
  
  sa: "अन्तःयात्रा जीवनस्य बाह्याभिव्यक्तेः अन्तर्निहितसत्तायाः दिशि एका मौनी प्रत्यावर्तनयात्रा अस्ति, यत्र सूर्यचन्द्रयोः प्रतिबिम्बयोः चेतनस्य अचेतनस्य"
},
 
descFull: {
  en: "and unconscious mind through the reflections of the Sun and Moon gives meaning to the existence of life; through this journey, the search for the inner self begins within the depths of body, mind, and consciousness; spirituality begins when being transcends the boundaries of external identity and learns to experience its inherent source; individuality is then not separation, but an independent expression of self-awareness and creativity; through the emptiness, memory, and experience within, this journey advances deeply toward self-knowledge, self-realization, and the fundamental essence of life—toward vibration and resonance;",
  
  bn: "অচেতন মনের সংমিশ্রণই জীবনের অস্তিত্বকে অর্থবহ করে তোলে; এই যাত্রায় দেহ, মন ও চেতনার গভীরে আত্মসত্তার অনুসন্ধান শুরু হয়; আধ্যাত্মিকতার সূচনা ঘটে যখন বাহ্যিক পরিচয়ের সীমা অতিক্রম করে সত্তা নিজের অন্তর্নিহিত উৎসকে অনুভব করতে শেখে; ব্যক্তিস্বাতন্ত্রতা তখন বিচ্ছিন্নতা নয়, বরং নিজস্ব সচেতনতা ও সৃজনশীলতার স্বতন্ত্র প্রকাশ; অন্তরের শূন্যতা, স্মৃতি ও অনুভবের মধ্য দিয়ে এই যাত্রা আত্মজ্ঞান, আত্মোপলব্ধি এবং জীবনের মৌলিক সারবস্তু—যা স্পন্দন ও অনুরণের দিকে এক গভীর অগ্রগতি ঘটায়;",
  
  hi: " ही जीवन के अस्तित्व को अर्थपूर्ण बनाता है; इस यात्रा में शरीर, मन और चेतना की गहराइयों में आत्मसत्ता की खोज आरंभ होती है; आध्यात्मिकता की शुरुआत तब होती है जब सत्ता बाहरी पहचान की सीमाओं को पार करके अपने अंतर्निहित स्रोत को अनुभव करना सीखती है; व्यक्तित्व तब अलगाव नहीं, बल्कि अपनी चेतना और सृजनशीलता की स्वतंत्र अभिव्यक्ति बन जाता है; अंतर्मन की शून्यता, स्मृति और अनुभव के माध्यम से यह यात्रा आत्मज्ञान, आत्मबोध और जीवन के मूल सार—स्पंदन और अनुनाद—की ओर एक गहरी प्रगति का मार्ग प्रशस्त करती है;",
  
  sa: "च मनसोः समन्वय एव जीवनस्य अस्तित्वं सार्थकं करोति; अस्यां यात्रायां शरीरस्य मनसः चेतनायाश्च गभीरतायाम् आत्मसत्तायाः अन्वेषणम् आरभ्यते; आध्यात्मिकतायाः आरम्भः तदा भवति यदा सत्ता बाह्यपरिचयस्य सीमाः अतिक्रम्य स्वस्य अन्तर्निहितं स्रोतः अनुभूयितुं शिक्षते; व्यक्तिस्वातन्त्र्यं तदा पृथक्त्वं न भवति, अपि तु स्वकीयचेतनायाः सृजनशीलतायाश्च स्वतन्त्राभिव्यक्तिः भवति; अन्तःशून्यतया स्मृत्या अनुभवेण च एषा यात्रा आत्मज्ञानस्य आत्मबोधस्य जीवनस्य मूलसारस्य च—स्पन्दनस्य अनुनादस्य च—दिशि गभीरं प्रगतिं साधयति;"
},

