  sa: "प्राकृतिकजीवनं प्रकृतेः स्वकीयेन लयेन सत्तायाः स्थितेः पुनर्गठनस्य च स्वाभाविकी अभिव्यक्तिः अस्ति; सत्तायाः पुनःस्थापनम् अत्र कश्चित् पृथग् परिवर्तनः न, अपि"
