  bn: "ইথারীয় স্তরে শক্তি, আলো ও মহাজাগতিক কণার প্রবাহ নতুন বিন্যাস সৃষ্টি করে, যেখানে পৃথিবীর ভূমি ও চন্দ্রের উপস্থিতি পরস্পরের প্রতিচ্ছবি হয়ে ওঠে; এই পুনর্গঠন কোনো বিচ্ছিন্ন ঘটনা নয়, বরং সময়, মহাকর্ষ ও প্রাণশক্তির ধারাবাহিক প্রভাবে গঠিত এক জীবন্ত প্রক্রিয়া; পৃথিবী ও চন্দ্রের এই সংযোগ প্রকৃতির গর্ভে অন্তর্নিহিত পরম সত্তার শাশ্বত ছন্দকে প্রতিফলিত করে, যেখানে চন্দ্রের উপস্থিতি বা জন্ম প্রকৃতির সৃজনশীলতাকে সমৃদ্ধ করে; তাই সূর্য, চন্দ্র ও পৃথিবীর সংযোগ জীবন ও প্রকৃতিকে সামঞ্জস্যপূর্ণ করে তোলে;",
  
  hi: "प्रकाश और ब्रह्मांडीय कणों का प्रवाह नए विन्यासों का निर्माण करता है, जहाँ पृथ्वी की भूमि और चंद्रमा की उपस्थिति एक-दूसरे का प्रतिबिंब बन जाती हैं; यह पुनर्गठन कोई पृथक घटना नहीं, बल्कि समय, गुरुत्वाकर्षण और प्राणशक्ति के निरंतर प्रभाव से निर्मित एक जीवंत प्रक्रिया है; पृथ्वी और चंद्रमा का यह संबंध प्रकृति के गर्भ में अंतर्निहित परम सत्ता की शाश्वत लय को प्रतिबिंबित करता है, जहाँ चंद्रमा की उपस्थिति या जन्म प्रकृति की सृजनशीलता को समृद्ध करता है; इसलिए सूर्य, चंद्रमा और पृथ्वी का संबंध जीवन और प्रकृति को सामंजस्यपूर्ण बनाता है;",
  
  sa: "ईथरीयस्तरे ऊर्जा, प्रकाशः, ब्रह्माण्डीयकणानां प्रवाहश्च नूतनान् विन्यासान् निर्मान्ति, यत्र पृथिव्याः भूमिः चन्द्रस्य च उपस्थितिः परस्परस्य प्रतिबिम्बे भवतः; एतत् पुनर्गठनं कश्चित् पृथग्घटनः न, अपि तु कालस्य गुरुत्वाकर्षणस्य प्राणशक्तेश्च निरन्तरप्रभावेन निर्मिता एका जीवन्तप्रक्रिया अस्ति; पृथिव्याः चन्द्रस्य च एषः सम्बन्धः प्रकृतेः गर्भे अन्तर्निहितस्य परमसत्तायाः शाश्वतं छन्दं प्रतिबिम्बयति, यत्र चन्द्रस्य उपस्थितिः जन्म वा प्रकृतेः सृजनशीलतां समृद्धयति; अतः सूर्यस्य चन्द्रस्य पृथिव्याश्च सम्बन्धः जीवनं प्रकृतिं च सामञ्जस्यपूर्णं करोति;"
