  sa: "शून्यतायाः जीवनम् इति एका निरन्तरा पूर्णता बोध्यते, अपरतः जीवनं पीढीपरम्परया विद्यमानं भवति; जीवनं शून्यावस्थायाः स्थिरता न, अपि तु अनन्तजीवनस्य"
