descFull: {
  en: "stillness of an empty state, but an inherent space of infinite possibility and creation; within this emptiness, the fundamental forces of nature hold the various forms of life and are expressed through knowledge, experience, thought, and creativity within culture—a single dimension of connection with life grants life its wholeness; experiences arising from nature acquire new meaning and form within culture; consequently, a subtle bridge is created between emptiness, life, and culture, where life is one and imperishable; the natural flow of nature and cultural consciousness become interconnected, creating an uninterrupted evolutionary way of life;",
  
  bn: "বরং অসীম জীবনের সম্ভাবনা ও সৃষ্টির এক অন্তর্নিহিত পরিসর; এই শূন্যতার মধ্যেই প্রকৃতির মৌলিক শক্তি জীবনের বিভিন্ন রূপকে ধারণ করে এবং জ্ঞানের অনুভব, চিন্তা ও সৃজনশীলতার মাধ্যমে সংস্কৃতিতে প্রকাশিত হয়—একটি মাত্রা জীবনের সংযোগই জীবনকে পূর্ণতা দান করে; প্রকৃতি থেকে উদ্ভূত অভিজ্ঞতা সংস্কৃতির মধ্যে নতুন অর্থ ও রূপ লাভ করে; ফলস্বরূপ, শূন্যতা, জীবন ও সংস্কৃতির মধ্যে এক সূক্ষ্ম সেতু তৈরি করে, যেখানে জীবন এক ও অবিনশ্বর; প্রকৃতির স্বাভাবিক প্রবাহ এবং সাংস্কৃতিক চেতনা পরস্পরের সঙ্গে যুক্ত হয়ে এক অবিচ্ছিন্ন বিবর্তনশীল জীবনধারা সৃষ্টি করে;",

  hi: "अनंत जीवन की संभावना और सृष्टि का एक अंतर्निहित क्षेत्र है; इसी शून्यता में प्रकृति की मूल शक्तियाँ जीवन के विभिन्न रूपों को धारण करती हैं और ज्ञान, अनुभूति, विचार तथा सृजनशीलता के माध्यम से संस्कृति में अभिव्यक्त होती हैं—जीवन के साथ संबंध की एक ही मात्रा जीवन को पूर्णता प्रदान करती है; प्रकृति से उत्पन्न अनुभव संस्कृति में नए अर्थ और रूप प्राप्त करते हैं; फलतः शून्यता, जीवन और संस्कृति के बीच एक सूक्ष्म सेतु निर्मित होता है, जहाँ जीवन एक और अविनश्वर है; प्रकृति का स्वाभाविक प्रवाह और सांस्कृतिक चेतना परस्पर जुड़कर एक अविच्छिन्न विकासशील जीवनधारा का निर्माण करते हैं;",

  sa: "सम्भावनायाः सृष्टेश्च एकम् अन्तर्निहितं क्षेत्रम् अस्ति; अस्यां शून्यतायां प्रकृतेः मूलशक्तयः जीवनस्य विविधरूपाणि धारयन्ति तथा ज्ञानस्य अनुभूतेः चिन्तनस्य सृजनशीलतायाश्च माध्यमेन संस्कृतौ अभिव्यजन्ते—जीवनेन सह सम्बन्धस्य एका मात्रा जीवनं पूर्णतां नयति; प्रकृतेः उद्भूताः अनुभूतयः संस्कृतौ नूतनम् अर्थं रूपं च प्राप्नुवन्ति; फलतः शून्यतायाः जीवनस्य संस्कृतेश्च मध्ये एकं सूक्ष्मं सेतुं निर्मीयते, यत्र जीवनम् एकम् अविनश्वरं च अस्ति; प्रकृतेः स्वाभाविकः प्रवाहः सांस्कृतिकचेतना च परस्परं सम्बद्धौ भूत्वा एकम् अविच्छिन्नं विकासशीलं जीवनप्रवाहं निर्मतः;"
},

width: 2,
 size: "Acrylic on canvas, 46'' x 33'' 2018"
