descShort: {
  en: "Natural life may be expressed through the presence or absence of life, where the unconscious connection reveals the inner relationship",

  bn: "প্রাকৃতিক জীবন অর্থে জীবনের উপস্থিতি অথবা অনুপস্থিতির মধ্যে প্রকাশ পায়, যেখানে অচেতন সংযোগ প্রকৃতির দেহ-মনের সঙ্গে জীবনের",

  hi: "प्राकृतिक जीवन जीवन की उपस्थिति अथवा अनुपस्थिति के माध्यम से व्यक्त हो सकता है, जहाँ अचेतन संबंध प्रकृति के शरीर और मन के साथ जीवन के अंतर्निहित",

  sa: "प्राकृतिकजीवनम् जीवनस्य उपस्थितेः अनुपस्थितेर्वा मध्ये प्रकाशते, यत्र अचेतनसम्बन्धः प्रकृतेः शरीरमनसोः सह जीवनस्य अन्तर्निहितं सम्बन्धं"
},
 
descFull: {
  en: "between life and the body and mind of nature; within the natural flow of nature, impressions accumulated at the unconscious level gradually soften, opening the way for the simple and spontaneous expression of life; the interaction of air, water, earth, light, and heat carries the fundamental rhythm of life and awakens inner balance; life free from impressions is then not in conflict with nature, but moves with its natural rhythm toward new experience, creativity, and liberated existence;",

  bn: "অন্তর্লীন সম্পর্ককে প্রকাশ করে; প্রকৃতির স্বাভাবিক প্রবাহে অচেতন স্তরে সঞ্চিত সংস্কার ধীরে ধীরে শিথিল হয়ে জীবনের সহজ ও স্বতঃস্ফূর্ত প্রকাশের পথ উন্মুক্ত করে; বায়ু, জল, মাটি, আলো ও তাপের পারস্পরিক ক্রিয়া জীবনের মৌলিক ছন্দকে ধারণ করে এবং অন্তর্গত ভারসাম্যকে জাগ্রত করে; সংস্কারমুক্ত জীবন তখন প্রকৃতির সঙ্গে বিরোধ নয়, বরং তার স্বাভাবিক গতির সঙ্গে যুক্ত হয়ে নতুন অনুভব, সৃজনশীলতা ও মুক্ত অস্তিত্বের দিকে অগ্রসর হয়;",

  hi: "संबंध को प्रकट करता है; प्रकृति के स्वाभाविक प्रवाह में अचेतन स्तर पर संचित संस्कार धीरे-धीरे शिथिल होते हैं और जीवन की सहज तथा स्वाभाविक अभिव्यक्ति का मार्ग खोलते हैं; वायु, जल, मिट्टी, प्रकाश और ताप की पारस्परिक क्रिया जीवन की मूल लय को धारण करती है और आंतरिक संतुलन को जागृत करती है; संस्कारमुक्त जीवन तब प्रकृति के विरोध में नहीं, बल्कि उसकी स्वाभाविक गति के साथ जुड़कर नए अनुभव, सृजनशीलता और मुक्त अस्तित्व की ओर अग्रसर होता है;",

  sa: "Sप्रकाशयति; प्रकृतेः स्वाभाविके प्रवाहे अचेतनस्तरे सञ्चिताः संस्काराः शनैः शनैः शिथिलाः भवन्ति तथा जीवनस्य सहजस्वाभाविकाभिव्यक्तेः मार्गम् उद्घाटयन्ति; वायोः जलस्य भूमेः प्रकाशस्य तापस्य च पारस्परिकक्रिया जीवनस्य मूलं छन्दं धारयति तथा अन्तर्निहितं साम्यं जागरयति; संस्कारमुक्तं जीवनं तदा प्रकृत्या सह विरोधे न भवति, अपि तु तस्याः स्वाभाविकगतिना सह सम्बध्य नूतनानुभवस्य सृजनशीलतायाः मुक्तास्तित्वस्य च दिशि अग्रसरति;"
},

