descShort: {
  en: "As a fundamental basis of life, this reflection represents the inherent knowledge of the source of life or the realization of the essence",
  
  bn: "জীবনের মৌলিক ভিত্তি হিসেবে এই প্রতিফলন জীবন উৎসের অন্তর্নিহিত জ্ঞান অথবা পিতা ও মাতার সারসত্তার উপলব্ধিকে প্রতিফলিত",

  hi: "जीवन के मूल आधार के रूप में यह प्रतिबिंब जीवन-स्रोत के अंतर्निहित ज्ञान अथवा पिता और माता के सारतत्त्व की अनुभूति को प्रतिबिंबित करता है, जो देह",
  
  sa: "जीवनस्य मूलाधाररूपेण अयं प्रतिबिम्बः जीवनस्रोतसः अन्तर्निहितं ज्ञानम् अथवा पितृमातृसारतत्त्वस्य अनुभूतिं प्रतिबिम्बयति, यत् देहस्य मनसश्च विविधेषु",
},

 
descFull: {
  en: "of the father and mother, reflected through the various levels of body and mind, where the reality of life becomes perceptible through self-realization; the central circles and geometric arrangement embody the outward flow from the inner source, where the dream becomes a symbol of profound potential; through yoga and spiritual practice, the refinement of body and mind unfolds as a continuous process of reconstruction through the interaction of stable life experience, feeling, and consciousness; the arrangement from above downward and from the center outward indicates the expansion of the life flow; through this reflection, life advances toward its own source, structure, and latent potential;",
  
  bn: "করে, যা দেহ ও মনের বিভিন্ন স্তরে প্রতিফলিত হয়, যেখানে আত্ম-উপলব্ধির মাধ্যমে জীবনের বাস্তবতা পরিলক্ষিত হয়; কেন্দ্রীয় বৃত্ত ও জ্যামিতিক বিন্যাসে চিত্রিত অভ্যন্তরীণ উৎস থেকে বহির্মুখী প্রবাহকে ধারণ করে, যেখানে স্বপ্ন এক গভীর সম্ভাবনার প্রতিমূর্তি; যোগ-সাধনার মাধ্যমে দেহ-মনের সংস্কার এখানে স্থিতিশীল জীবন অভিজ্ঞতা, অনুভব ও চেতনার পারস্পরিক প্রতিক্রিয়ায় ক্রমাগত পুনর্গঠনের প্রক্রিয়া; উপরের থেকে নিম্নমুখী এবং কেন্দ্র থেকে বহির্মুখী বিন্যাস জীবনপ্রবাহের বিস্তারকে নির্দেশ করে; এই প্রতিফলনের মধ্য দিয়ে জীবন নিজের উৎস, গঠন ও অন্তর্লীন সম্ভাবনার দিকে অগ্রসর হয়;",

  hi: "और मन के विभिन्न स्तरों में अभिव्यक्त होता है, जहाँ आत्म-बोध के माध्यम से जीवन की वास्तविकता अनुभूत होती है; केंद्रीय वृत्तों और ज्यामितीय विन्यास में आंतरिक स्रोत से बाह्यमुखी प्रवाह को धारण किया गया है, जहाँ स्वप्न गहन संभावना का प्रतीक बनता है; योग-साधना के माध्यम से देह-मन का संस्कार स्थिर जीवन-अनुभव, अनुभूति और चेतना की पारस्परिक प्रतिक्रिया द्वारा निरंतर पुनर्गठन की प्रक्रिया के रूप में विकसित होता है; ऊपर से नीचे और केंद्र से बाहर की ओर विस्तृत विन्यास जीवन-प्रवाह के विस्तार को दर्शाता है; इस प्रतिबिंब के माध्यम से जीवन अपने स्रोत, संरचना और अंतर्निहित संभावना की ओर अग्रसर होता है;",
  
  sa: "स्तरेषु अभिव्यज्यते, यत्र आत्मबोधेन जीवनस्य वास्तविकता अनुभूयते; केन्द्रीयवृत्तेषु ज्यामितीयविन्यासे च आन्तरिकस्रोतसः बहिर्मुखं प्रवाहं धारयति, यत्र स्वप्नं गहनसम्भावनायाः प्रतीकं भवति; योगसाधनया देहमनसोः संस्कारः स्थिरजीवनानुभवस्य अनुभूतेश्च चेतनायाश्च पारस्परिकप्रतिक्रियया निरन्तरपुनर्गठनस्य प्रक्रियारूपेण विकसितः भवति; ऊर्ध्वात् अधोमुखं केन्द्रात् बहिर्मुखं च विन्यासः जीवनप्रवाहस्य विस्तारं निर्दिशति; अनेन प्रतिबिम्बेन जीवनं स्वस्रोतसः संरचनायाः अन्तर्निहितसम्भावनायाश्च दिशि अग्रसरति;",
},

