descShort: {
  en: "Love for life appears here as a symbolic form of embryonic harmony, where the central vibration of the feminine and masculine",
 
  bn: "জীবনের প্রতি প্রেম এখানে ভ্রূণীয় সম্প্রীতির এক প্রতীকী রূপ, যেখানে নারী-পুরুষ সত্তার কেন্দ্রীয় স্পন্দনকে ঘিরে জীবনের বিভিন্ন স্তর পরস্পরের সঙ্গে যুক্ত হয়েছে; বৃত্ত, সর্পিল রেখা ও",
  
 
  hi: "जीवन के प्रति प्रेम यहाँ भ्रूणीय समरसता के एक प्रतीकात्मक रूप के रूप में प्रकट होता है, जहाँ स्त्री और पुरुष सत्ताओं के केंद्रीय स्पंदन को घेरते हुए जीवन के",
  
  sa: "जीवने प्रति प्रेम अत्र भ्रूणीयसामञ्जस्यस्य प्रतीकरूपेण प्रकटते, यत्र स्त्रीपुरुषसत्तयोः केन्द्रीयस्पन्दनं परितः जीवनस्य विविधाः स्तराः परस्परं सम्बध्यन्ते; वृत्तानि",
},

 
descFull: {
  en: "essences connects the different levels of life with one another; circles, spiral lines, and geometric arrangements express the inner development of the embryo and the continuous transformation of life force; love here is an inherent power that embraces and develops the union of body and mind, reaching toward the ultimate destination of individual existence; this rhythm of advancing from the embryonic state toward mature life reflects the continuity of eternal life and becomes a guide along the path of spirituality; self-love becomes the guiding direction of this inner journey, through which life advances toward fullness through creation, harmony, and transformation;",

  bn: "জ্যামিতিক বিন্যাস ভ্রূণের অন্তর্গত বিকাশ এবং জীবনশক্তির ধারাবাহিক রূপান্তরকে প্রকাশ করে; প্রেম এখানে দেহ ও মনের মিলনকে ধারণ ও বিকশিত করার এক অন্তর্নিহিত শক্তি, যা ব্যক্তিসত্তার পরম গন্তব্যকে স্পর্শ করে; ভ্রূণীয় অবস্থান থেকে পরিণত জীবনের দিকে অগ্রসর হওয়ার এই ছন্দ শাশ্বত জীবনের ধারাবাহিকতাকে প্রতিফলিত করে, এবং আধ্যাত্মিকতার পথপ্রদর্শক হয়ে ওঠে; আত্মপ্রেম এই অন্তর্যাত্রার পথনির্দেশক দিশা হয়ে ওঠে, যেখানে সৃষ্টি, সামঞ্জস্য ও রূপান্তরের মধ্য দিয়ে জীবন তার পূর্ণতার দিকে এগিয়ে যায়;",
  
  
  hi: "विभिन्न स्तर एक-दूसरे से जुड़े हैं; वृत्त, सर्पिल रेखाएँ और ज्यामितीय विन्यास भ्रूण के आंतरिक विकास तथा जीवन-शक्ति के निरंतर रूपांतरण को अभिव्यक्त करते हैं; प्रेम यहाँ देह और मन के मिलन को धारण तथा विकसित करने वाली एक अंतर्निहित शक्ति है, जो व्यक्तिगत सत्ता के परम गंतव्य को स्पर्श करती है; भ्रूणीय अवस्था से परिपक्व जीवन की ओर बढ़ने की यह लय शाश्वत जीवन की निरंतरता को प्रतिबिंबित करती है और आध्यात्मिकता के मार्ग की दिशा दिखाती है; आत्म-प्रेम इस अंतर्मुखी यात्रा का मार्गदर्शक बनता है, जहाँ सृष्टि, सामंजस्य और रूपांतरण के माध्यम से जीवन अपनी पूर्णता की ओर अग्रसर होता है;",
  
  sa: "सर्पिलरेखाः ज्यामितीयविन्यासाश्च भ्रूणस्य अन्तर्गतविकासं जीवनशक्तेश्च निरन्तरं रूपान्तरणं प्रकाशयन्ति; प्रेम अत्र देहमनसोः मिलनं धारयित्वा विकसितुं समर्था अन्तर्निहिता शक्तिः, या व्यक्तिसत्तायाः परमगन्तव्यं स्पृशति; भ्रूणीयावस्थातः परिपक्वजीवनस्य दिशि गमनस्य अयं छन्दः शाश्वतजीवनस्य सातत्यं प्रतिबिम्बयति तथा आध्यात्मिकतायाः मार्गदर्शकः भवति; आत्मप्रेम अस्य अन्तर्मुखयात्रायाः मार्गदर्शकं भवति, यत्र सृष्टेः सामञ्जस्यस्य रूपान्तरणस्य च माध्यमेन जीवनं पूर्णतायाः दिशि अग्रसरति;",
},

