descShort: {
  en: "The reflection of nature is expressed here through the symbolic connection between the zero hour and the cycle of time; the central circle",
  
  bn: "প্রকৃতির প্রতিফলন এখানে শূন্য ঘণ্টা ও কালচক্রের প্রতীকী সংযোগের মাধ্যমে প্রকাশিত হয়েছে; কেন্দ্রীয় বৃত্ত প্রকৃতির সময়ের অন্তর্গত গতি ধারণ",

  hi: "प्रकृति का प्रतिबिंब यहाँ शून्य क्षण और कालचक्र के प्रतीकात्मक संबंध के माध्यम से अभिव्यक्त होता है; केंद्रीय वृत्त समय के भीतर प्रकृति की अंतर्निहित",
  
  sa: "अत्र प्रकृतेः प्रतिबिम्बनं शून्यकालस्य कालचक्रस्य च प्रतीकात्मकसम्बन्धेन प्रकाशते; केन्द्रीयवृत्तं काले प्रकृतेः अन्तर्निहितं गतिचक्रं धारयति, परितः स्थितः",
},
 
descFull: {
   en: "embodies the inner movement of nature through time, while the surrounding geometric arrangement indicates the transformation and recurrence of nature's different phases; the zero hour represents an inherent field of harmony between emerging life and the temporal rhythm of nature, becoming a starting point for a new ecosystem; light, darkness, movement, and stillness reveal their interconnected relationship within the continuity of life; in this painting, nature is not confined by time, but embraces each phase of time, continually reconstructing itself through its own rhythm and carrying life toward new possibilities;",
  
   bn: "করে, আর চারপাশের জ্যামিতিক বিন্যাস প্রকৃতির বিভিন্ন পর্যায়ের পরিবর্তন ও পুনরাবর্তনকে নির্দেশ করে; শূন্য ঘণ্টা থেকে উদ্ভূত জীবন ও প্রকৃতির সময়ের সামঞ্জস্যতার এক অন্তর্নিহিত পরিসর, যা এক নতুন বাস্তুতন্ত্রের সূচনা বিন্দু; অর্থাৎ আলো, অন্ধকার, গতি ও স্থিরতার পারস্পরিক সম্পর্ক জীবনের ধারাবাহিকতাকে প্রকাশ করে; এই চিত্রে প্রকৃতি সময়ের মধ্যে আবদ্ধ নয়, বরং সময়ের প্রতিটি পর্যায়কে ধারণ করে নিজের ছন্দে পুনর্গঠিত হয় এবং জীবনকে নতুন সম্ভাবনার দিকে এগিয়ে নেয়;",

  hi: "गति को धारण करता है, जबकि चारों ओर का ज्यामितीय विन्यास प्रकृति के विभिन्न चरणों के परिवर्तन और पुनरावर्तन को दर्शाता है; शून्य क्षण उभरते जीवन और प्रकृति की समय-लय के बीच एक अंतर्निहित सामंजस्य का क्षेत्र है, जो एक नए पारिस्थितिक तंत्र का प्रारंभिक बिंदु बनता है; प्रकाश, अंधकार, गति और स्थिरता का पारस्परिक संबंध जीवन की निरंतरता को प्रकट करता है; इस चित्र में प्रकृति समय से सीमित नहीं, बल्कि समय के प्रत्येक चरण को धारण करते हुए अपनी लय में निरंतर पुनर्गठित होती है और जीवन को नई संभावनाओं की ओर ले जाती है;",
  
  sa: "ज्यामितीयविन्यासश्च प्रकृतेः विभिन्नानां चरणानां परिवर्तनं पुनरावर्तनं च निर्दिशति; शून्यकालः उद्भवमानजीवनस्य प्रकृतेः काललयस्य च अन्तर्निहितसामञ्जस्यस्य क्षेत्रं भवति, यत् नूतनपारिस्थितिकतन्त्रस्य प्रारम्भबिन्दुरूपेण प्रकटते; प्रकाशस्य अन्धकारस्य गत्याः स्थिरतायाश्च पारस्परिकसम्बन्धः जीवनस्य सातत्यं प्रकाशयति; अस्मिन् चित्रे प्रकृतिः कालेन सीमिता न, अपि तु कालस्य प्रत्येकं चरणं धारयित्वा स्वलयेन निरन्तरं पुनर्गठिता भवति तथा जीवनं नूतनसम्भावनानां दिशि नयति;",
},

