  hi: "स्थान और काल की प्रकृति में शून्यता का जीवन और प्रकृति का स्पंदन सूर्य, चंद्र और पृथ्वी के प्रतीकात्मक संबंध के माध्यम से अभिव्यक्त होता है; देह और",
  
  sa: "स्थानस्य कालस्य च प्रकृतौ शून्यतायाः जीवनं प्रकृतेः स्पन्दनं च सूर्यचन्द्रपृथिवीनां प्रतीकात्मकसम्बन्धेन प्रकाशते; देहमनसोः अमूर्तरूपं कल्पनाजगतः स्पर्शं",
