descShort: {
  en: "In the pillar of life and nature, the vertical arrangement becomes a symbol of the deep foundation of life and the inner forces of",

  bn: "জীবন-প্রকৃতির স্তম্ভে উল্লম্ব বিন্যাস জীবনের গভীর ভিত্তি ও প্রকৃতির অন্তর্গত শক্তির প্রতীক হয়ে ওঠে, যেখানে পৃথিবীর কেন্দ্রীয় অন্তঃসার দেহকৃতি",
    
  hi: "जीवन-प्रकृति के स्तंभ में ऊर्ध्वाधर विन्यास जीवन की गहरी आधारभूमि और प्रकृति की अंतर्निहित शक्तियों का प्रतीक बनता है, जहाँ पृथ्वी का केंद्रीय सार और चारों",
  
  sa: "जीवनप्रकृतिस्तम्भे ऊर्ध्वविन्यासः जीवनस्य गभीराधारस्य प्रकृतेः अन्तर्निहितशक्तीनां च प्रतीकरूपेण भवति, यत्र पृथिव्याः केन्द्रीयसारः परितः स्थितानि वृत्ताकारस्तराणि",
},
 
descFull: {
  en: "nature, where the central essence of the Earth and the surrounding circular layers express the continuity of earthly refinement, memory, and accumulated life experience; the grey life of spirituality becomes colored, representing not merely stillness and stability, but an inner state preceding transformation; when the forces of nature connect with life, the stillness of the Kundalini cycle gradually moves toward transformation; this pillar therefore embodies an uninterrupted relationship among Earth, life, and the inner forces of existence;",

  bn: "এবং চারপাশের বৃত্তাকার স্তরগুলো ভূ-সংস্কার, স্মৃতি ও জীবনের সঞ্চিত অভিজ্ঞতার ধারাকে প্রকাশ করে; আধ্যাত্মিকতার ধূসর জীবন রঙিন হয়ে ওঠে, এখানে নিশ্চলতা ও স্থিরতার একমাত্র প্রতীক নয়, বরং পরিবর্তনের পূর্ববর্তী এক অন্তর্লীন অবস্থা; প্রকৃতির শক্তি যখন জীবনের সঙ্গে যুক্ত হয়, তখন কুণ্ডলিনী চক্রের সেই স্থিরতা ধীরে ধীরে রূপান্তরের দিকে অগ্রসর হয়; এই স্তম্ভ তাই পৃথিবী, জীবন ও অন্তর্গত শক্তির মধ্যে এক অবিচ্ছিন্ন সম্পর্ককে ধারণ করে;",
    
  hi: "ओर स्थित वृत्ताकार स्तर भू-संस्कार, स्मृति तथा संचित जीवन-अनुभव की धारा को अभिव्यक्त करते हैं; आध्यात्मिकता का धूसर जीवन रंगों में परिवर्तित होता है, जो केवल निश्चलता और स्थिरता का प्रतीक नहीं, बल्कि रूपांतरण से पूर्व की एक अंतर्निहित अवस्था है; जब प्रकृति की शक्ति जीवन से जुड़ती है, तब कुंडलिनी चक्र की स्थिरता धीरे-धीरे रूपांतरण की ओर अग्रसर होती है; यह स्तंभ पृथ्वी, जीवन और अंतर्निहित शक्ति के बीच एक अविच्छिन्न संबंध को धारण करता है;",
  
  sa: "च भूसंस्कारस्य स्मृतेः सञ्चितजीवनानुभवस्य च प्रवाहं प्रकाशयन्ति; आध्यात्मिकतायाः धूसरजीवनं वर्णमयं भवति, यत् केवलं निश्चलतायाः स्थिरतायाश्च प्रतीकं न, अपि तु रूपान्तरणात् पूर्वस्य अन्तर्निहितावस्थायाः प्रतीकम्; यदा प्रकृतेः शक्तिः जीवनेन सह सम्बध्यते, तदा कुण्डलिनीचक्रस्य स्थिरता शनैः रूपान्तरणस्य दिशि अग्रसरति; अयं स्तम्भः पृथिव्याः जीवनस्य अन्तर्निहितशक्तेः च मध्ये अविच्छिन्नं सम्बन्धं धारयति;",
},

